const stdout = $input.item.json.stdout;

if (!stdout || stdout.trim() === '') {
  return [];
}

// Literal \n'leri gerçek newline'a çevir ve satırlara böl
const lines = stdout.replace(/\\n/g, '\n').split('\n');

// Sadece FILE satırlarını al (başlık ve özet satırlarını atla)
const fileLines = lines.filter(line => 
  line.includes('\tFILE\t') && line.includes('.fastq.gz')
);

const projectId = $('Set Project ID').first().json.PROJECT_ID;

return fileLines.map(line => {
  // Tab ile böl ve ilk kolonu (filename) al
  const filename = line.split('\t')[0];

  const beforeS = filename.split('_S')[0];
  let sampleId, analysisType;

  if (beforeS.endsWith('-D') || beforeS.endsWith('-R')) {
    sampleId = beforeS.slice(0, -2);
    analysisType = 'TSO500_HT';
  } else {
    sampleId = beforeS;
    analysisType = 'TSO500_ctDNA';
  }

  return {
    json: {
      filename: filename,
      sample_id: sampleId,
      analysis_type: analysisType,
      PROJECT_ID: projectId
    }
  };
});

// Tüm önceki item'ları al
const items = $input.all();

// sample_id'ye göre grupla
const sampleGroups = {};

for (const item of items) {
  const sampleId = item.json.sample_id;

  if (!sampleGroups[sampleId]) {
    sampleGroups[sampleId] = {
      sample_id: sampleId,
      files: [],
      PROJECT_ID: item.json.PROJECT_ID
    };
  }

  sampleGroups[sampleId].files.push(item.json.filename);
}

// Her sample için ayrı item oluştur
return Object.values(sampleGroups).map(group => ({
  json: {
    sample_id: group.sample_id,
    file_count: group.files.length,
    files: group.files,
    PROJECT_ID: group.PROJECT_ID
  }
}));

const stdout = $input.item.json.stdout;
const inputId = stdout.match(/INPUT_ID=(\S+)/)[1];
const outputId = stdout.match(/OUTPUT_ID=(\S+)/)[1];

return {
  json: {
    sample_id: $input.item.json.sample_id,
    PROJECT_ID: $input.item.json.PROJECT_ID,
    samplesheet_id: $input.item.json.samplesheet_id,
    input_folder_id: inputId,
    output_folder_id: outputId
  }
};

