  }
}));

// Mevcut klasörleri al
const existingFoldersOutput = $('Check Existing Folders').first().json.stdout;
const existingFolders = existingFoldersOutput 
  ? existingFoldersOutput.trim().split('\n').filter(Boolean) 
  : [];

const sampleId = $('Set Project ID').item.json.SAMPLE_ID;

// Sample ID ile eşleşenleri bul (tam eşleşme veya -T1, -T2 gibi)
const matchingFolders = existingFolders.filter(folder => 
  folder === sampleId || folder.match(new RegExp(`^${sampleId.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}-T\\d+$`))
);

// En yüksek T numarasını bul
let maxT = -1;
matchingFolders.forEach(folder => {
  if (folder === sampleId) {
    maxT = Math.max(maxT, 0);
  } else {
    const match = folder.match(/-T(\d+)$/);
    if (match) {
      maxT = Math.max(maxT, parseInt(match[1]));
    }
  }
});

// Yeni klasör adı belirle
const uploadFolder = maxT === -1 
  ? sampleId 
  : `${sampleId}-T${maxT + 1}`;

// Tüm dosyalar için upload_folder ve yeni dosya adı ekle
return $('Code in JavaScript1').all().map(item => {
  const originalFilename = item.json.filepath;
  const newFilename = originalFilename.replace(sampleId, uploadFolder);

  return {
    json: {
      ...item.json,
      upload_folder: uploadFolder,
      upload_filename: newFilename
    }
  };
});

